// Generated by `npx @polishd/next init`. Edit freely — `--force` backs up
// this file before regenerating it.
import type { NextRequest } from "next/server";
import { withPolishdSession } from "@polishd/next/proxy";

export function proxy(request: NextRequest) {
  return withPolishdSession(request);
}

// Next statically parses config.matcher, so it must be an inline literal
// here. Excluding all of /api is required — under Next 16 + Turbopack a
// matcher that touches /api breaks the whole /api segment.
// Only pages need the session cookie, so the routes that serve files and
// data stay out too: the sandboxed previews (dozens per grid, cached by the
// CDN), the registry, the MCP server, the agent files, metadata routes and
// public/.
export const config = {
  matcher: [
    "/((?!api|_next/static|_next/image|favicon|assets|preview/|r/|mcp|skill|llms\\.txt|sitemap\\.xml|robots\\.txt|manifest\\.webmanifest|opengraph-image|icon|apple-icon|cursors/|.*\\.svg$).*)",
  ],
};
